+describe.skipIf(process.platform !== 'win32')('ShellExecutionService (Windows Integration)', () => {
+  it('should execute embedded double quotes successfully via pwsh.exe and preserve quotes', async () => {
+    // Assert that complex commands execute successfully and output "preserved" with exit code 0.
+    const command = 'node -e "console.log(\\"preserved\\")"';
+    let output = '';
+
+    const handle = await ShellExecutionService.execute(
+      command,
+      process.cwd(),
+      (event) => {
+        if (event.type === 'data') {
+          output += event.chunk;
+        }
+      },
+      new AbortController().signal,
+      false,
+      {
+        sanitizationConfig: {
+          allowedEnvironmentVariables: [],
+          blockedEnvironmentVariables: [],
+          enableEnvironmentVariableRedaction: false,
+        },
+        sandboxManager: new NoopSandboxManager(),
+      }
+    );
+
+    const result = await handle.result;
+    expect(result.exitCode).toBe(0);
+    expect(output.trim()).toBe('preserved');
+  });
+});
